    function buildSummaryFromPolicy(policy, modelCtx, rawEstimatedInputTokens, finalEstimatedInputTokens, extra = {}) {
        return {
            policy: policySnapshotCopy(policy),
            bypassed: Boolean(policy?.bypassed),
            bypassReason: policy?.bypassReason || '',
            maintenanceMode: Boolean(policy?.maintenanceMode),
            thinkingLevelApplied: policy?.thinkingPlan?.level || 'auto',
            sessionSaltApplied: Boolean(policy?.thinkingPlan?.sessionSalt),
            sanitizeThinkingConflictApplied: Boolean(policy?.thinkingPlan?.sanitizeThinkingConflict),
            nativeThinkingModeApplied: policy?.thinkingPlan?.nativeMode || (policy?.thinkingPlan?.sanitizeThinkingConflict ? 'allow' : 'preset'),
            routingLevelApplied: policy?.routingLevel || 'off',
            jailbreakApplied: Boolean(policy?.jailbreak),
            extraInjectionApplied: Boolean(policy?.extraInjection),
            inputModeApplied: policy?.inputMode || 'off',
            toolOuterCoverApplied: Boolean(policy?.useOuterCover),
            toolPlusArmorInjected: Boolean(policy?.useToolTransport && !policy?.isGoogleNative && !policy?.bypassed),
            settingsVersion: runtime.settings.settingsVersion || SETTINGS_VERSION,
