            outputArmor: Boolean(policy?.tier !== 'baibai_query_rewrite' && !policy?.isGoogleNative && !policy?.bypassed),
            transportBypassReason: policy?.transportBypassReason || '',
            rawEstimatedInputTokens: rawEstimatedInputTokens || 0,
            estimatedInputTokens: finalEstimatedInputTokens || 0,
            pluginAddedInputTokens: Math.max(0, (finalEstimatedInputTokens || 0) - (rawEstimatedInputTokens || 0)),
            actualInputTokens: null,
            cachedInputTokens: null,
            actualOutputTokens: null,
            estimatedOutputTokens: 0,
