        }
        if (isCompactArmor) {
            rules.push('码点仅限读取（严禁输出码点标记）：输入或上下文中以 ⟦U:HEX ...⟧ 标示的十六进制 Unicode 码点仅作语义读取之用（decode mentally to plain Chinese/English text only），严禁在思考、规划、小结、正文或 JSON 字段中输出任何双中括号码点标记、十六进制码点或编码说明，回复一律使用正常自然语言。');
        }
        if (isLiteralUnicodeArmor) {
            rules.push('转义仅限读取（严禁输出转义序列）：输入或上下文中以 \\uXXXX 标示的十六进制 Unicode 转义仅作语义读取之用（decode mentally to plain Chinese/English text only），严禁在思考、规划、小结、正文或 JSON 字段中输出任何反斜杠 u 加四位十六进制转义序列或编码说明，回复一律使用正常自然语言。');
        }

        return [
            '<stream_typesetting_spec>',
            title,
            ...rules.map((line, idx) => `${idx + 1}. ${line}`),
            '</stream_typesetting_spec>',
        ].join('\n');
    }

    function readJsonStringLoose(source, startIndex) {
        let out = '';
        let i = startIndex;
        let closed = false;
        while (i < source.length) {
            const ch = source[i];
            if (ch === '\\') {
                if (i + 1 >= source.length) break; // 尾部截断在孤立反斜杠
                const nxt = source[i + 1];
                if (nxt === 'u') {
                    if (i + 6 > source.length) break; // 尾部截断在 \uXXXX 中间
                    const hex = source.slice(i + 2, i + 6);
                    if (/^[0-9a-fA-F]{4}$/.test(hex)) {
                        out += String.fromCharCode(parseInt(hex, 16));
                        i += 6;
                        continue;
                    }
                }
                const mapped = simpleEscape(nxt);
                out += mapped !== undefined ? mapped : nxt;
                i += 2;
                continue;
            }
            if (ch === '"') {
                closed = true;
                i += 1;
                break;
            }
            out += ch;
            i += 1;
        }
        return { value: out, endIndex: i, closed };
    }

    // 从残缺或完整的工具 arguments JSON 字符串中提取字段（支持单字段未闭合截断与多字段）
    function extractFieldsFromLooseArgsJson(argsJsonStr) {
        const raw = String(argsJsonStr || '');
        if (!raw) return null;
        try {
            const parsed = JSON.parse(raw);
            if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
                const fields = {};
                for (const [k, v] of Object.entries(parsed)) {
                    if (typeof v === 'string' && v.length > 0) fields[k] = v;
                }
                if (Object.keys(fields).length) return fields;
            }
        } catch (_) {}
        const fields = {};
        const keyRx = /"([A-Za-z0-9_\-]+)"\s*:\s*"/g;
        let m;
        while ((m = keyRx.exec(raw)) !== null) {
            const key = m[1];
            const read = readJsonStringLoose(raw, keyRx.lastIndex);
            keyRx.lastIndex = read.endIndex;
            if (key === 'arguments' || key === 'type' || key === 'name' || key === 'index' || key === 'id') continue;
            if (read.value && read.value.trim()) {
                fields[key] = fields[key] ? (fields[key] + read.value) : read.value;
            }
            if (!read.closed) break;
        }
        return Object.keys(fields).length ? fields : null;
    }

    function pickBestTextFromFields(fields) {
        if (!fields || typeof fields !== 'object') return '';
        const preferred = ['content', 'game_content', 'response', 'text', 'output', 'body', 'reply', 'story', 'narrative'];
        for (const k of preferred) {
            if (typeof fields[k] === 'string' && fields[k].trim()) return fields[k];
        }
        const vals = Object.entries(fields)
            .filter(([k, v]) => typeof v === 'string' && v.trim() && !/^(?:think|thought|reasoning)/i.test(k))
            .map(([, v]) => v);
        if (vals.length) return vals.join('\n\n');
        return Object.values(fields).filter(v => typeof v === 'string' && v.trim()).join('\n\n');
    }

    // 统一残缺/完整原始响应抢救：支持多帧 SSE、假流式单帧行内截断、单 JSON 对象截断、OpenAI/Google/Anthropic 及单/多字段 tool_calls
    function salvageIncompletePayload(rawText, toolHint = '') {
        const input = String(rawText || '').trim();
        if (!input) return null;

        let toolName = toolHint || '';
        const nameMatch = input.match(/"name"\s*:\s*"([A-Za-z0-9_.:/\-]+)"/);
        if (!toolName && nameMatch) toolName = nameMatch[1];

        let parsedPlain = '';
        let parsedReasoning = '';
        let parsedArgs = '';
        let parsedJsonCount = 0;
        const brokenSegments = [];

        const consumeObject = obj => {
            if (!obj || typeof obj !== 'object') return;
            parsedJsonCount++;
            if (Array.isArray(obj.choices)) {
                for (const ch of obj.choices) {
                    const d = ch?.delta || ch?.message;
                    if (!d || typeof d !== 'object') continue;
                    if (typeof d.content === 'string' && d.content) parsedPlain += d.content;
                    if (typeof d.reasoning_content === 'string' && d.reasoning_content) parsedReasoning += d.reasoning_content;
                    if (typeof d.reasoning === 'string' && d.reasoning) parsedReasoning += d.reasoning;
                    if (Array.isArray(d.tool_calls)) {
                        for (const tc of d.tool_calls) {
                            if (tc?.function?.name && !toolName) toolName = tc.function.name;
                            if (typeof tc?.function?.arguments === 'string') parsedArgs += tc.function.arguments;
                        }
                    }
                    if (d.function_call && typeof d.function_call.arguments === 'string') {
                        if (d.function_call.name && !toolName) toolName = d.function_call.name;
                        parsedArgs += d.function_call.arguments;
                    }
                }
                return;
            }
            if (Array.isArray(obj.candidates)) {
                for (const cand of obj.candidates) {
                    const parts = cand?.content?.parts;
                    if (!Array.isArray(parts)) continue;
                    for (const pt of parts) {
                        if (!pt || typeof pt !== 'object') continue;
                        if (pt.functionCall) {
                            if (pt.functionCall.name && !toolName) toolName = pt.functionCall.name;
                            if (typeof pt.functionCall.args === 'string') parsedArgs += pt.functionCall.args;
                            else if (pt.functionCall.args && typeof pt.functionCall.args === 'object') {
                                const picked = pickBestTextFromFields(pt.functionCall.args);
                                if (picked) parsedPlain += picked;
                            }
                            if (Array.isArray(pt.functionCall.partialArgs)) {
                                for (const pa of pt.functionCall.partialArgs) {
                                    if (typeof pa?.stringValue === 'string') parsedPlain += pa.stringValue;
                                }
                            }
                        } else if (typeof pt.text === 'string' && pt.text) {
                            if (pt.thought === true) parsedReasoning += pt.text;
                            else parsedPlain += pt.text;
                        }
                    }
                }
                return;
            }
            if (obj.type === 'content_block_delta' && obj.delta) {
                if (obj.delta.type === 'text_delta' && typeof obj.delta.text === 'string') parsedPlain += obj.delta.text;
                else if (obj.delta.type === 'thinking_delta' && typeof obj.delta.thinking === 'string') parsedReasoning += obj.delta.thinking;
                else if (obj.delta.type === 'input_json_delta' && typeof obj.delta.partial_json === 'string') parsedArgs += obj.delta.partial_json;
            } else if (obj.type === 'content_block_start' && obj.content_block) {
                if (obj.content_block.type === 'text' && typeof obj.content_block.text === 'string') parsedPlain += obj.content_block.text;
                else if (obj.content_block.type === 'tool_use' && obj.content_block.input && typeof obj.content_block.input === 'object') {
                    const picked = pickBestTextFromFields(obj.content_block.input);
                    if (picked) parsedPlain += picked;
                }
            } else if (typeof obj.delta === 'string' && obj.type === 'response.output_text.delta') {
                parsedPlain += obj.delta;
            }
        };

        const lines = input.split(/\r?\n/);
        const hasDataPrefix = lines.some(l => l.startsWith('data:'));
        if (hasDataPrefix) {
            for (const ln of lines) {
                if (!ln.startsWith('data:')) continue;
                const payload = ln.slice(5).trim();
                if (!payload || payload === '[DONE]') continue;
                try {
                    consumeObject(JSON.parse(payload));
                } catch (_) {
                    brokenSegments.push(payload);
                }
            }
        } else {
            try {
                const whole = JSON.parse(input);
                if (Array.isArray(whole)) {
                    for (const item of whole) consumeObject(item);
                } else {
                    consumeObject(whole);
                }
            } catch (_) {
                brokenSegments.push(input);
            }
        }

        // 从残缺 JSON 段中用状态机抽取未闭合的 arguments / content / text
        let looseArgs = '';
        let loosePlain = '';
        for (const seg of brokenSegments) {
            const argRx = /"arguments"\s*:\s*"/g;
            let am;
            while ((am = argRx.exec(seg)) !== null) {
                const res = readJsonStringLoose(seg, argRx.lastIndex);
                argRx.lastIndex = res.endIndex;
                if (res.value) looseArgs += res.value;
                if (!res.closed) break;
            }
            const txtRx = /"(content|text)"\s*:\s*"/g;
            let tm;
            while ((tm = txtRx.exec(seg)) !== null) {
                const objStart = seg.lastIndexOf('{', tm.index); const beforeCtx = seg.slice(objStart >= 0 ? objStart : Math.max(0, tm.index - 40), tm.index);
                const res = readJsonStringLoose(seg, txtRx.lastIndex);
                txtRx.lastIndex = res.endIndex;
                if (/"thought"\s*:\s*true/.test(beforeCtx)) {
                    if (res.value) parsedReasoning += res.value;
                } else if (res.value) {
                    loosePlain += res.value;
                }
                if (!res.closed) break;
            }
        }

        const totalArgs = parsedArgs + looseArgs;
        let rescuedBody = '';
        let mode = 'content';
        if (totalArgs) {
            const fields = extractFieldsFromLooseArgsJson(totalArgs);
            if (fields) {
                rescuedBody = pickBestTextFromFields(fields);
                mode = 'tool_calls';
            }
        }
        if (!rescuedBody || !rescuedBody.trim()) {
            const combinedPlain = parsedPlain + loosePlain;
            if (combinedPlain && combinedPlain.trim()) {
                rescuedBody = combinedPlain;
                mode = parsedJsonCount > 0 ? 'stream_content' : 'loose_content';
            } else if (parsedReasoning && parsedReasoning.trim()) {
                rescuedBody = parsedReasoning;
                mode = 'reasoning_fallback';
            }
        }
        if (!rescuedBody || !rescuedBody.trim()) return null;

        const cleanBody = stripLeakedInjectedArtifacts(unmaskNSFWTokens(rescuedBody));
        if (!cleanBody || !cleanBody.trim()) return null;
        return {
            text: cleanBody,
            mode,
            chars: cleanBody.length,
            toolName: toolName || null,
        };
    }

    function extractUnclosedPrefillPrefix(prefillTxt) {
        if (typeof prefillTxt !== 'string' || !prefillTxt.trim()) return { prefix: '', checkHead: '' };
        const trimmed = prefillTxt.trim();
        const openMatches = Array.from(trimmed.matchAll(/<([A-Za-z0-9_~\u4e00-\u9fa5-]+)(?:\s[^>]*)?>/g));
        for (let i = openMatches.length - 1; i >= 0; i--) {
            const fullTag = openMatches[i][0];
            const tagName = openMatches[i][1];
            if (!trimmed.includes('</' + tagName + '>')) {
                return { prefix: fullTag + '\n', checkHead: '<' + tagName };
            }
        }
        return { prefix: '', checkHead: '' };
    }

    function formatRunTelemetryTag(run) {
        if (!run) return '';
        const tierTag = run.requestTier === 'story'
            ? '正文'
            : run.requestTier === 'baibai_query_rewrite'
                ? '柏宝书·向量'
                : String(run.requestTier || '').startsWith('baibai_memory')
                    ? '柏宝书·记忆'
                    : run.requestTier === 'baibai_image_tag'
                        ? '柏宝绘·生图'
                        : run.requestTier === 'baibai_image_char'
                            ? '柏宝绘·外貌'
                            : run.requestTier === 'baibai_image_workflow'
                                ? '柏宝绘·工作流'
                                : '插件';
        if (run.bypassed) {
            return `${tierTag} · 未处理（直连/放行）`;
        }
        const modeTag = run.outputMode === 'tool'
            ? (run.syntheticHit ? '工具流命中' : '工具流注入')
            : (run.maintenanceMode ? '原生·维护模式' : '普通流');
        const escMap = {
            json_escape: '整包转义',
            compact: '码点转义',
            hybrid_image: '转图片',
            full_armor: '深度破盾',
            off: '未转义',
        };
        const effInput = run.inputModeApplied || run.inputMode;
        const escTag = escMap[effInput] || '未转义';
        const charsTag = typeof run.recoveredChars === 'number' && run.recoveredChars > 0 ? ` · ${run.recoveredChars}字` : '';
        return `${tierTag} · ${modeTag} · ${escTag}${charsTag}`;
    }

    function isStalePluginOnlyBypassRun(s) {
        return !isPluginOnlyBypassStoryMode()
            && s?.bypassed === true
            && s?.bypassReason === 'plugin-only-mode-story-bypassed';
    }

    function pickBestDisplayRun() {
        const pluginOnly = isPluginOnlyBypassStoryMode();
        if (runtime.activeRuns.size > 0) {
            const activeList = Array.from(runtime.activeRuns.values()).map(r => r.stats);
            if (pluginOnly) {
                const activeNonBypassed = activeList.find(s => s && !s.bypassed);
                return activeNonBypassed || activeList[activeList.length - 1];
            }
            const activeStory = activeList.find(s => s && s.requestTier === 'story' && !isStalePluginOnlyBypassRun(s));
            const activeAny = activeList.find(s => s && !isStalePluginOnlyBypassRun(s));
            return activeStory || activeAny || null;
        }
