    function applyFullContextCodepointArmorInPlace(messages, criticalOnly = false, opts = null) {
        if (!Array.isArray(messages) || !messages.length) return 0;
        const protectTrailingAssistant = !opts || opts.protectTrailingAssistant !== false;
        const isLiteralU = opts && opts.format === 'literal_u';
        const termEncoder = isLiteralU
            ? (raw => literalUnicodeEncode(unmaskNSFWTokens(raw, { decodeCompact: false }), true))
            : (raw => compactEncode(unmaskNSFWTokens(raw, { decodeCompact: false }), true));
        const packetHasNsfw = (opts && typeof opts.hasNsfwSignal === 'boolean')
            ? opts.hasNsfwSignal
            : detectMessagesNsfwSignal(messages);
        let hitCount = 0;
        const armorSensitiveTermsOutsidePadding = (rawStr, useCriticalOnly) => {
            if (typeof rawStr !== 'string' || !rawStr) return rawStr;
            const padSplitRx = /((?:^(?:SPECIAL INSTRUCTION:[^\r\n]+\r?\n?|\[Session-ID:[^\]]+\]\r?\n?)+)|<(?:inert_lexical_entropy_buffer|inert_reference_padding|ambient_calibration_padding|ambient_reference_padding|stream_typesetting_spec|audit_check)\b[^>]*>[\s\S]*?<\/(?:inert_lexical_entropy_buffer|inert_reference_padding|ambient_calibration_padding|ambient_reference_padding|stream_typesetting_spec|audit_check)>)/gi;
            return rawStr.split(padSplitRx).map((seg, idx) => {
                if (idx % 2 === 1 || !seg) return seg;
                // 跳过 XML/HTML 标签、已有 ⟦U:...⟧ 块、字面量 \uXXXX、JSON 键名及 JSONPatch 路径字符串 ("/秦依梦/部位/花穴")
                return seg.split(/(<[^>]*>|⟦U:[0-9a-fA-F\s]+⟧|\\u[0-9a-fA-F]{4}|"(?:[^"\\]|\\.)*"(?=\s*:)|"\/(?:[^"\\\r\n]+\/)+[^"\\\r\n]*")/g).map((part, pIdx) => {
                    if (pIdx % 2 === 1 || !part) return part;
                    const activeRx = useCriticalOnly
                        ? (packetHasNsfw ? COMPACT_WITH_NSFW_RX : CRITICAL_REDLINE_TERM_RX)
                        : (packetHasNsfw ? HIGH_RISK_RESCUE_TERM_RX : FULL_ARMOR_NO_NSFW_RX);
                    if (part.includes(SYNTHETIC_TOOL_NAME)) {
                        return part.split(SYNTHETIC_TOOL_NAME).map(sub =>
                            sub.replace(activeRx, m => {
                                hitCount += 1;
                                return termEncoder(m);
                            })
                        ).join(SYNTHETIC_TOOL_NAME);
                    }
                    return part.replace(activeRx, m => {
                        hitCount += 1;
                        return termEncoder(m);
                    });
                }).join('');
            }).join('');
        };
        const allowToolRoleContent = Boolean(opts && opts.allowToolRoleContent === true && !isLiteralU);
        for (let i = 0; i < messages.length; i++) {
            const msg = messages[i];
            if (!msg) continue;
            if (isProtectedToolOrSignatureMessage(msg)) {
                if (!(allowToolRoleContent && String(msg.role || '').toLowerCase() === 'tool' && typeof msg.content === 'string')) {
                    continue;
                }
            }
            const isTrailingAssistant = protectTrailingAssistant
                && i === messages.length - 1
                && ['assistant', 'model'].includes(String(msg.role || '').toLowerCase());
            // 紧贴生成光标前的尾部 assistant（开启 5.3 尾部预填充或 continue 续写）仅按红线词保护，减少续写位置直接吐码诱导
            const msgCriticalOnly = criticalOnly || isTrailingAssistant;
            if (typeof msg.content === 'string') {
                const next = armorSensitiveTermsOutsidePadding(msg.content, msgCriticalOnly);
                if (next !== msg.content) msg.content = next;
            } else if (Array.isArray(msg.content)) {
                msg.content = msg.content.map(part => {
                    if (isTextLike(part)) {
                        const next = armorSensitiveTermsOutsidePadding(part.text, msgCriticalOnly);
                        if (next !== part.text) return { ...part, text: next };
                    }
                    return part;
                });
            }
        }
        return hitCount;
    }

    // ==================== [纯流式实时连字符还原引擎（全帧实时透传，零后台二次重发）] ====================
    function createResilientPlainSseResponse(firstResponse, prepared, run = null) {
        if (!firstResponse.body || typeof TransformStream === 'undefined') return firstResponse;
        const unmaskOn = true;
