                choices: [{ index: 0, delta: deltaObj, finish_reason: finishReason }],
            }) + '\n\n';

        (async () => {
            const decoder = new TextDecoder();
            const contentUnmasker = new StreamingUnmasker(unmaskOn);
            const reasoningUnmasker = new StreamingUnmasker(unmaskOn);
            const toolArgUnmaskers = new Map();
            let reasoningAccum = '';
