            let arrBuf = '';
            let sawDone = false;
            let emittedAnyFrame = false;
            let sawToolCallPayload = false;

            const feedToolArgChunk = (slotKey, rawArgStr) => {
                if (typeof rawArgStr !== 'string' || !rawArgStr) return rawArgStr;
