                    id: String(c?.id || ''),
                    type: String(c?.type || 'function'),
                    name: String(fn.name || c?.name || ''),
                    arguments: parsedArgs,
                    rawArguments: typeof rawArgs === 'string' ? rawArgs : JSON.stringify(rawArgs ?? {}),
                    function: { name: String(fn.name || c?.name || ''), arguments: typeof rawArgs === 'string' ? rawArgs : JSON.stringify(rawArgs ?? {}) },
                };
            });
            const defText = normalizedCalls.map(c => typeof c.arguments === 'string' ? c.arguments : JSON.stringify(c.arguments)).join('\n');
            let text = defText;
            if (typeof formatterFn === 'function') {
                const r = await formatterFn({ calls: normalizedCalls, toolCalls: normalizedCalls, defaultText: defText, stream: false, channel: 'main' });
                text = typeof r === 'string' ? r : (r && typeof r === 'object' ? String(r.output ?? r.text ?? r.content ?? '') : String(r ?? ''));
            }
            if (typeof preprocFn === 'function') {
                const pr = await preprocFn({ buffer: text, final: true, state: {}, stream: false, channel: 'main' });
                if (typeof pr === 'string') text = pr;
                else if (pr && typeof pr === 'object' && pr.output !== undefined) text = String(pr.output ?? '');
            }
            return text;
        };
        if (Array.isArray(parsed.choices)) {
            for (const ch of parsed.choices) {
                const msg = ch?.message;
                if (!msg || typeof msg !== 'object') continue;
                const calls = Array.isArray(msg.tool_calls) ? msg.tool_calls : (msg.function_call ? [msg.function_call] : []);
                if (!calls.length) continue;
                try {
                    const toolText = await formatCalls(calls);
                    msg.content = msg.content ? `${msg.content}\n${toolText}` : toolText;
                    delete msg.tool_calls;
                    delete msg.function_call;
                    if (ch.finish_reason === 'tool_calls' || ch.finish_reason === 'function_call') ch.finish_reason = 'stop';
                } catch (_) {}
            }
        }
        return parsed;
    }

    async function handleResilientPlainJsonResponse(firstResponse, run = null, hasInnerSPresetJsonHook = false) {
        const unmaskOn = true;
        let rawText = '';
        try {
            rawText = await firstResponse.clone().text();
        } catch (_) {
            return firstResponse;
        }
        if (!rawText || !rawText.trim()) return firstResponse;
        try {
            const parsed = JSON.parse(rawText);
            if (parsed && typeof parsed === 'object') {
                if (parsed.error || parsed.promptFeedback?.blockReason) {
                    return firstResponse;
                }
                let recoveredChars = 0;
                const finishReasons = [];
                const unmaskJsonValuesDeep = (val, stripArtifacts = false) => {
                    if (typeof val === 'string') {
                        const dec = unmaskNSFWTokens(val);
                        return stripArtifacts ? stripLeakedInjectedArtifacts(dec) : dec;
                    }
                    if (Array.isArray(val)) return val.map(item => unmaskJsonValuesDeep(item, false));
                    if (val && typeof val === 'object') {
                        const out = {};
                        for (const k of Object.keys(val)) {
                            out[k] = unmaskJsonValuesDeep(val[k], k === 'content');
                        }
                        return out;
                    }
                    return val;
                };
                if (Array.isArray(parsed.choices)) {
                    for (const ch of parsed.choices) {
                        if (ch?.finish_reason && !finishReasons.includes(ch.finish_reason)) finishReasons.push(ch.finish_reason);
                        const msg = ch?.message;
                        if (msg && typeof msg === 'object') {
                            if (typeof msg.content === 'string') {
                                if (unmaskOn) msg.content = stripLeakedInjectedArtifacts(unmaskNSFWTokens(msg.content));
                                recoveredChars += msg.content.length;
                            }
                            if (typeof msg.reasoning_content === 'string' && unmaskOn) msg.reasoning_content = unmaskNSFWTokens(msg.reasoning_content);
                            if (typeof msg.reasoning === 'string' && unmaskOn) msg.reasoning = unmaskNSFWTokens(msg.reasoning);
                            if ((!msg.content || !String(msg.content).trim()) && (!Array.isArray(msg.tool_calls) || msg.tool_calls.length === 0)) {
                                let fallbackRsn = (typeof msg.reasoning_content === 'string' && msg.reasoning_content.trim())
                                    ? msg.reasoning_content
                                    : (typeof msg.reasoning === 'string' && msg.reasoning.trim() ? msg.reasoning : '');
                                if (!fallbackRsn && Array.isArray(msg.reasoning_details)) {
                                    const joinedRd = msg.reasoning_details
                                        .map(rd => (rd && typeof rd === 'object' ? (rd.text ?? rd.content ?? rd.summary ?? '') : ''))
                                        .filter(t => typeof t === 'string' && t.trim())
                                        .join('\n');
                                    if (joinedRd.trim()) fallbackRsn = unmaskOn ? unmaskNSFWTokens(joinedRd) : joinedRd;
                                }
                                if (fallbackRsn) {
                                    msg.content = unmaskOn ? stripLeakedInjectedArtifacts(fallbackRsn) : fallbackRsn;
                                    recoveredChars += msg.content.length;
                                }
                            }
                            if (Array.isArray(msg.tool_calls) && msg.tool_calls.length > 0) {
                                for (const tc of msg.tool_calls) {
                                    if (tc?.function && typeof tc.function.arguments === 'string') {
                                        try {
                                            const argObj = JSON.parse(tc.function.arguments);
                                            if (argObj && typeof argObj === 'object') {
                                                const decodedArgObj = unmaskOn ? unmaskJsonValuesDeep(argObj, false) : argObj;
                                                for (const v of Object.values(decodedArgObj)) {
                                                    if (typeof v === 'string') recoveredChars += v.length;
                                                }
                                                if (unmaskOn) tc.function.arguments = JSON.stringify(decodedArgObj);
                                            }
                                        } catch (_) {}
                                    }
                                }
                            }
                        }
                    }
                } else if (Array.isArray(parsed.candidates)) {
                    for (const cand of parsed.candidates) {
                        if (cand?.finishReason && !finishReasons.includes(cand.finishReason)) finishReasons.push(cand.finishReason);
                        const parts = cand?.content?.parts;
                        if (Array.isArray(parts)) {
                            let hasNonThoughtText = false;
                            const thoughtTexts = [];
                            for (const pt of parts) {
                                if (pt && typeof pt.text === 'string') {
                                    if (unmaskOn) {
                                        pt.text = pt.thought === true
                                            ? unmaskNSFWTokens(pt.text)
                                            : stripLeakedInjectedArtifacts(unmaskNSFWTokens(pt.text));
                                    }
                                    if (pt.thought !== true && pt.text.trim()) {
                                        hasNonThoughtText = true;
                                        recoveredChars += pt.text.length;
                                    } else if (pt.thought === true && pt.text.trim()) {
                                        thoughtTexts.push(pt.text);
                                    }
                                }
                                if (pt?.functionCall?.args && typeof pt.functionCall.args === 'object') {
                                    if (unmaskOn) pt.functionCall.args = unmaskJsonValuesDeep(pt.functionCall.args, false);
                                    if (typeof pt.functionCall.args.content === 'string') {
                                        hasNonThoughtText = true;
                                        recoveredChars += pt.functionCall.args.content.length;
                                    }
                                }
                            }
                            if (!hasNonThoughtText && thoughtTexts.length > 0 && !parts.some(p => p?.functionCall)) {
                                const rescuedText = unmaskOn ? stripLeakedInjectedArtifacts(thoughtTexts.join('\n')) : thoughtTexts.join('\n');
                                parts.push({ text: rescuedText });
                                recoveredChars += rescuedText.length;
                            }
                        }
                    }
                } else if (Array.isArray(parsed.content)) {
                    // Anthropic Messages 非流式 JSON 响应还原（覆盖 text / thinking / tool_use.input）
                    if (parsed.stop_reason && !finishReasons.includes(parsed.stop_reason)) finishReasons.push(parsed.stop_reason);
                    for (const blk of parsed.content) {
                        if (!blk || typeof blk !== 'object') continue;
                        if (blk.type === 'text' && typeof blk.text === 'string') {
                            if (unmaskOn) blk.text = stripLeakedInjectedArtifacts(unmaskNSFWTokens(blk.text));
                            recoveredChars += blk.text.length;
                        } else if (blk.type === 'thinking' && typeof blk.thinking === 'string') {
                            if (unmaskOn) blk.thinking = unmaskNSFWTokens(blk.thinking);
                        } else if (blk.type === 'tool_use' && blk.input && typeof blk.input === 'object') {
                            if (unmaskOn) blk.input = unmaskJsonValuesDeep(blk.input, false);
                            if (typeof blk.input.content === 'string') recoveredChars += blk.input.content.length;
                        }
                    }
                }
                try {
                    if (run) {
                        run.record({ data: parsed });
                        applyUsageToRun(run, parsed);
                        if (recoveredChars > 0) run.content(recoveredChars);
                        run.update({
                            ...(finishReasons.length > 0 ? { finishReasons } : {}),
                            ...(recoveredChars > 0 ? { endedCleanly: true } : {}),
                        });
                    }
                } catch (_) {}
                await applySPresetNonStreamingToolConsumptionIfNeeded(parsed, hasInnerSPresetJsonHook);
                if (!unmaskOn && !hasInnerSPresetJsonHook) return firstResponse;
                return copyResponse(firstResponse, JSON.stringify(parsed), 'application/json; charset=utf-8');
            }
        } catch (_) {
            if (!unmaskOn) return firstResponse;
            return copyResponse(firstResponse, unmaskNSFWTokens(rawText), 'application/json; charset=utf-8');
        }
        return firstResponse;
    }

    function teeCacheResponse(response, meta = {}) {
        if (!response || !response.body || typeof response.body.tee !== 'function') return response;
        let branches;
        try {
            branches = response.body.tee();
        } catch (_) {
            return response;
        }
        const [forPipeline, forCache] = branches;
        (async () => {
            const reader = forCache.getReader();
            const chunks = [];
            let total = 0;
            let readErr = null;
            try {
                while (true) {
                    const { done, value } = await reader.read();
                    if (done) break;
                    if (value && value.byteLength && total < STREAM_LIMIT) {
                        const remain = STREAM_LIMIT - total;
                        const piece = value.byteLength <= remain ? value.slice() : value.slice(0, remain);
                        chunks.push(piece);
                        total += piece.byteLength;
                    }
                }
            } catch (err) {
                readErr = err;
            } finally {
                try { reader.releaseLock(); } catch (_) {}
                if (total > 0) {
                    try {
                        const data = new Uint8Array(total);
                        let offset = 0;
                        for (const c of chunks) { data.set(c, offset); offset += c.byteLength; }
                        let tailText = '';
                        try { tailText = new TextDecoder('utf-8').decode(data.slice(Math.max(0, total - 4096))); } catch (_) {}
                        runtime.lastRawStream = {
                            at: Date.now(),
                            url: String(meta.url || ''),
                            toolName: meta.toolName || '',
                            status: response.status,
                            bytes: total,
                            complete: tailText.includes('[DONE]') && !readErr,
                            error: readErr ? String(readErr.message || readErr) : null,
                            data,
                        };
                    } catch (_) {}
                }
            }
        })();
        return new Response(forPipeline, {
            status: response.status,
            statusText: response.statusText,
            headers: new Headers(response.headers),
        });
    }

    async function salvageLastRawResponseIntoChat() {
        const rec = runtime.lastRawStream;
        if (!rec || !rec.bytes || !rec.data) {
            notify('warning', '暂无可抢救的响应缓存');
            return { ok: false, reason: 'no_cache' };
        }
        let rawText = '';
        try {
            rawText = new TextDecoder('utf-8').decode(rec.data);
        } catch (err) {
            notify('error', '缓存解码失败：' + (err?.message || String(err)));
            return { ok: false, reason: 'decode_failed' };
        }
        const rescued = salvageIncompletePayload(rawText, rec.toolName || '');
        if (!rescued || !rescued.text || !rescued.text.trim()) {
            notify('warning', '最近一次响应缓存中未提取到正文');
            return { ok: false, reason: 'empty_salvage' };
        }
        let stCtx = null;
        for (const host of hostWindows()) {
            try {
                const ctx = host?.SillyTavern?.getContext?.();
                if (ctx && Array.isArray(ctx.chat)) { stCtx = ctx; break; }
            } catch (_) {}
        }
        if (!stCtx) {
            notify('error', '未获取到酒馆聊天上下文，无法写入');
            return { ok: false, reason: 'no_context', text: rescued.text };
        }
        const message = {
            name: stCtx.name2 || 'Assistant',
            is_user: false,
            is_system: false,
            send_date: Date.now(),
            mes: rescued.text,
            extra: { salvagedByTwintail: true },
        };
        try {
            stCtx.chat.push(message);
            if (typeof stCtx.saveChat === 'function') await stCtx.saveChat();
            if (typeof stCtx.addOneMessage === 'function') {
                stCtx.addOneMessage(message, { scroll: true });
            } else if (typeof stCtx.reloadCurrentChat === 'function') {
                await stCtx.reloadCurrentChat();
            }
            notify('success', `已抢救写入 ${rescued.text.length} 字`);
            return { ok: true, chars: rescued.text.length, mode: rescued.mode };
        } catch (err) {
            notify('error', '写入聊天失败：' + (err?.message || String(err)));
            return { ok: false, reason: 'write_failed', error: err?.message || String(err) };
        }
    }

    function drainStops(list) {
        while (Array.isArray(list) && list.length) {
