    // v4.5.13B：原生思考三档
    const NATIVE_THINKING_MODE_LABELS = Object.freeze({ follow: '跟随', allow: '允许', preset: '跟随预设', forbid: '禁止' });
    const NATIVE_THINKING_MODE_HINTS = Object.freeze({
        follow: '跟随正文页设置',
