    function clearPanelStops() {
        drainStops(runtime.panelStops);
    }

    function syncConfigPanelViewport() {
        const panel = runtime.panel;
        const view = panel?.ownerDocument?.defaultView;
        if (!panel || !view) return;
        const viewportHeight = Number(view.visualViewport?.height || view.innerHeight || 0);
        if (viewportHeight > 0) {
            panel.style.setProperty('--ufi-viewport-height', `${Math.round(viewportHeight)}px`);
        }
    }

    function closeConfigPanel() {
        const panel = runtime.panel;
        if (!panel) return;
        panel.classList.remove('visible');
        panel.setAttribute('aria-hidden', 'true');
        const focusTarget = runtime.lastFocusedElement;
        runtime.lastFocusedElement = null;
        try { focusTarget?.focus?.({ preventScroll: true }); } catch (_) {}
    }

    function setToolTransport(enabled, options = {}) {
        const next = enabled === true;
        runtime.settings.toolTransport = next;
        saveSettings();
        syncStPostProcessingForToolTransport();
        syncConfigPanel();
        if (options.notify !== false) {
            notify('success', next ? '工具调用抗截断已开启' : '工具调用抗截断已关闭');
        }
        return next;
    }

    function setToolOuterCoverEnabled(enabled, options = {}) {
        const next = enabled !== false;
        return applySchemaSetting('toolOuterCoverEnabled', next, {
            ...options,
            notice: next ? '激发模型思考（《最后一个观察者》）已开启' : '激发模型思考已关闭（仅使用纯工具回执）',
        });
    }

    function setInputMode(mode, options = {}) {
        const allowed = ['json_escape', 'compact', 'hybrid_image', 'full_armor'];
        if (mode === 'off' || mode === false) {
            runtime.settings.inputEscapeEnabled = false;
        } else if (allowed.includes(mode)) {
            runtime.settings.inputMode = mode;
            if (options.autoEnable !== false) runtime.settings.inputEscapeEnabled = true;
        } else {
            return runtime.settings.inputMode;
        }
        saveSettings();
        syncConfigPanel();
        if (options.notify !== false) {
            const labels = {
                json_escape: '输入整包转义',
                compact: '输入码点转义',
                hybrid_image: '输入转图片',
                full_armor: '深度破盾',
            };
            notify('success', runtime.settings.inputEscapeEnabled ? `输入转义已切换：${labels[runtime.settings.inputMode] || runtime.settings.inputMode}` : '输入转义已关闭');
        }
        return runtime.settings.inputMode;
    }

    function syncConfigPanel() {
        syncLauncherAppearance();
        const panel = runtime.panel;
        if (!panel) return;

        const masterOn = runtime.settings.pluginEnabled !== false;
        const masterRow = panel.querySelector('[data-role="masterCard"]');
        const masterSwitch = panel.querySelector('[data-role="pluginEnabled"]');
        const masterBadge = panel.querySelector('[data-role="masterState"]');
        const subWrap = panel.querySelector('[data-role="subControlsWrap"]');
        const pluginCtrlWrap = panel.querySelector('[data-role="pluginControlsWrap"]');
        const pluginMasterOffBanner = panel.querySelector('[data-role="pluginMasterOffBanner"]');
        const headDot = panel.querySelector('[data-role="headDot"]');
        const headState = panel.querySelector('[data-role="headState"]');

        if (masterSwitch) masterSwitch.checked = masterOn;
        if (masterRow) masterRow.classList.toggle('off', !masterOn);
        if (masterBadge) {
            masterBadge.textContent = masterOn ? '已开启' : '已关闭';
            masterBadge.className = 'ufi-state' + (masterOn ? '' : ' saving');
        }
        if (headDot) headDot.classList.toggle('off', !masterOn);
        if (headState) headState.textContent = masterOn ? '运行中 · 按当前策略协同保护中' : '已关闭 · 0 改动原样直连';
        if (subWrap) {
            subWrap.classList.toggle('ufi-disabled', !masterOn);
        }
        if (pluginCtrlWrap) {
            pluginCtrlWrap.classList.toggle('ufi-disabled', !masterOn);
        }
        if (pluginMasterOffBanner) {
            pluginMasterOffBanner.classList.toggle('hide', masterOn);
        }

        // 全局顶部：当前模型检测（纯只读 + 架构徽章）
        const modelCtx = resolveModelContext(null, '');
        const matchedProf = modelCtx.matchedProfile;
        const detectedName = modelCtx.detectedModel;
        const modelValueEl = panel.querySelector('[data-role="detectedModelDesc"]');
        const archChipEl = panel.querySelector('[data-role="detectedArchChip"]');
        if (modelValueEl) {
            modelValueEl.textContent = detectedName || '未读取到酒馆当前模型';
            modelValueEl.title = detectedName || '';
            modelValueEl.classList.toggle('muted', !detectedName);
        }
        if (archChipEl) {
            if (matchedProf) {
                archChipEl.textContent = `Gemini · ${matchedProf.toUpperCase()}`;
                archChipEl.className = 'ufi-chip';
            } else if (modelCtx.geminiFamily === 'no') {
                archChipEl.textContent = '非 Gemini';
                archChipEl.className = 'ufi-chip blue';
            } else if (modelCtx.geminiFamily === 'yes') {
                archChipEl.textContent = 'Gemini · 通用';
                archChipEl.className = 'ufi-chip';
            } else {
                archChipEl.textContent = '未知架构';
                archChipEl.className = 'ufi-chip warn';
            }
        }

        // 思考等级（4H/4C/4N/38F/4A -> hydrogenThinkingLevel；其余通用/非Gemini/未知 -> otherThinkingLevel）
        const hLevelSel = panel.querySelector('[data-role="storyThinkingLevel"]');
        const thinkingScopeChip = panel.querySelector('[data-role="thinkingScopeChip"]');
        const profileLevels = {
            '4h': ['auto', 'low', 'medium', 'high', 'xhigh'],
            '4c': ['auto', 'low', 'medium', 'high'],
            '4n': ['auto', 'low', 'medium', 'high', 'xhigh'],
            '4a': ['auto', 'low', 'high'],
            '38f': ['auto', 'low', 'medium', 'high'],
        };
        const isProfileModel = Boolean(matchedProf && profileLevels[matchedProf]);
        const allowedLevels = isProfileModel ? profileLevels[matchedProf] : ['auto', 'low', 'medium', 'high'];
        const rawThinkingVal = isProfileModel
            ? (runtime.settings.hydrogenThinkingLevel || DEFAULTS.hydrogenThinkingLevel)
            : (runtime.settings.otherThinkingLevel || DEFAULTS.otherThinkingLevel);
        let displayThinkingVal = rawThinkingVal;
        if (!allowedLevels.includes(displayThinkingVal)) {
            if (matchedProf === '4a') {
                displayThinkingVal = (displayThinkingVal === 'high' || displayThinkingVal === 'xhigh') ? 'high' : 'low';
            } else if (displayThinkingVal === 'xhigh') {
                displayThinkingVal = 'high';
            } else {
                displayThinkingVal = allowedLevels[0];
            }
        }
        const levelLabel = lv => (lv === 'auto' ? 'auto（默认）' : lv);
        if (hLevelSel) {
            hLevelSel.dataset.boundKey = isProfileModel ? 'hydrogenThinkingLevel' : 'otherThinkingLevel';
            hLevelSel.innerHTML = allowedLevels
                .map(level => `<option value="${level}">${levelLabel(level)}</option>`)
                .join('');
            hLevelSel.value = displayThinkingVal;
            hLevelSel.disabled = false;
        }
        if (thinkingScopeChip) {
            thinkingScopeChip.textContent = isProfileModel ? matchedProf.toUpperCase() : '通用';
            thinkingScopeChip.className = 'ufi-chip ' + (isProfileModel ? '' : 'gray');
        }

        // v4.5.13B：原生思考三档
        const nativeModeVal = runtime.settings.nativeThinkingMode || DEFAULTS.nativeThinkingMode;
        panel.querySelectorAll('input[name="ufi-native-think"]').forEach(radio => {
            const checked = radio.value === nativeModeVal;
            radio.checked = checked;
            radio.closest('.ufi-choice')?.classList.toggle('active', checked);
        });
        const forbidRow = panel.querySelector('[data-role="forbidEffortRow"]');
        if (forbidRow) {
            const pluginForbid = runtime.settings.externalPluginPolicyMode === 'custom' && runtime.settings.pluginNativeThinkingMode === 'forbid';
            forbidRow.classList.toggle('hide', !(nativeModeVal === 'forbid' || pluginForbid));
        }
        const forbidSel = panel.querySelector('[data-role="forbidReasoningEffort"]');
        if (forbidSel) forbidSel.value = runtime.settings.forbidReasoningEffort || DEFAULTS.forbidReasoningEffort;

        const extraInjSwitch = panel.querySelector('[data-role="extraInjectionEnabled"]');
        if (extraInjSwitch) extraInjSwitch.checked = runtime.settings.extraInjectionEnabled !== false;

        // v4.5.12：塞垃圾自定义内容
        const padSt = customPaddingStatus();
        const padLib = runtime.textLibrary || {};
        const padSwitch = panel.querySelector('[data-role="customPaddingEnabled"]');
        const padBox = panel.querySelector('[data-role="customPaddingBox"]');
        const padChip = panel.querySelector('[data-role="customPaddingChip"]');
        const padNote = panel.querySelector('[data-role="customPaddingNote"]');
        const padLoop = panel.querySelector('[data-role="customPaddingLoopFill"]');
        if (padSwitch) padSwitch.checked = padSt.enabled;
        if (padBox) padBox.classList.toggle('open', padSt.enabled);
        if (padChip) padChip.classList.toggle('hide', !padSt.effective);
        if (padLoop) padLoop.checked = runtime.settings.customPaddingLoopFill !== false;
        if (padNote) {
            padNote.textContent = !padSt.enabled
                ? '关闭时使用默认文本'
                : (padSt.effective
                    ? `头部 ${padSt.systemChars} 字 · 输入 ${padSt.userChars ? padSt.userChars + ' 字' : '复用头部'}`
                    : '尚未填写，暂用默认文本');
        }
        const padDoc = panel.ownerDocument;
        for (const [role, slot, countRole] of [
            ['customPaddingSystem', 'systemCustom', 'customPaddingSysCount'],
            ['customPaddingUser', 'userCustom', 'customPaddingUserCount'],
        ]) {
            const ta = panel.querySelector(`[data-role="${role}"]`);
            const val = String(padLib[slot] || '');
            if (ta && padDoc?.activeElement !== ta && ta.value !== val) ta.value = val;
            const cnt = panel.querySelector(`[data-role="${countRole}"]`);
            if (cnt) cnt.textContent = `${(ta && padDoc?.activeElement === ta ? ta.value : val).trim().length} 字`;
        }

        const autoBypassVertex = panel.querySelector('[data-role="autoBypassVertex"]');
        if (autoBypassVertex) autoBypassVertex.checked = runtime.settings.autoBypassVertex !== false;

        // 正文防路由 3 选 1
        const rLevel = runtime.settings.routingLevel || DEFAULTS.routingLevel;
        panel.querySelectorAll('input[name="ufi-routing-level"]').forEach(radio => {
            const checked = radio.value === rLevel;
            radio.checked = checked;
            radio.closest('.ufi-choice')?.classList.toggle('active', checked);
        });

        // 正文破甲与旗下 3 项子工具联动
        const jailbreakOn = runtime.settings.jailbreakEnabled !== false;
        const jailbreakSwitch = panel.querySelector('[data-role="jailbreakEnabled"]');
        const jailbreakSubBox = panel.querySelector('[data-role="jailbreakSubBox"]');
        const jailbreakOffBadge = panel.querySelector('[data-role="jailbreakOffBadge"]');
        if (jailbreakSwitch) jailbreakSwitch.checked = jailbreakOn;
        if (jailbreakSubBox) jailbreakSubBox.classList.toggle('ufi-disabled', !jailbreakOn);
        if (jailbreakOffBadge) jailbreakOffBadge.classList.toggle('hide', jailbreakOn);

        const toolOn = runtime.settings.toolTransport === true;
        const toolSwitch = panel.querySelector('[data-role="toolTransport"]');
        if (toolSwitch) toolSwitch.checked = toolOn;
        const outerCoverOn = runtime.settings.toolOuterCoverEnabled !== false;
        const outerCoverSwitch = panel.querySelector('[data-role="toolOuterCoverEnabled"]');
        const outerCoverRow = panel.querySelector('[data-role="toolOuterCoverRow"]');
        if (outerCoverSwitch) outerCoverSwitch.checked = outerCoverOn;
        if (outerCoverRow) outerCoverRow.classList.toggle('ufi-disabled', !toolOn);

        const escOn = runtime.settings.inputEscapeEnabled === true;
        const escSwitch = panel.querySelector('[data-role="inputEscapeEnabled"]');
        const escBox = panel.querySelector('[data-role="inputEscapeBox"]');
        if (escSwitch) escSwitch.checked = escOn;
        if (escBox) escBox.classList.toggle('open', escOn);
        panel.querySelectorAll('input[name="ufi-input-mode"]').forEach(radio => {
            const checked = radio.value === runtime.settings.inputMode;
            radio.checked = checked;
            radio.closest('.ufi-choice')?.classList.toggle('active', checked);
        });

        const prefillSwitch = panel.querySelector('[data-role="preserveTrailingPrefill"]');
        if (prefillSwitch) prefillSwitch.checked = runtime.settings.preserveTrailingPrefill !== false;

        // 插件 tab 与正文只处理插件提示
        const extEnabled = runtime.settings.externalPluginEnabled !== false;
        const extOnly = runtime.settings.externalPluginOnly === true;
        const extPolicyMode = runtime.settings.externalPluginPolicyMode === 'custom' ? 'custom' : 'follow';
        const extSwitch = panel.querySelector('[data-role="externalPluginEnabled"]');
        const extBox = panel.querySelector('[data-role="externalPluginBox"]');
        const extOnlySwitch = panel.querySelector('[data-role="externalPluginOnly"]');
        const storyOnlyWrap = panel.querySelector('[data-role="storyOnlyControlsWrap"]');
        const pluginOnlyBanner = panel.querySelector('[data-role="pluginOnlyStoryBanner"]');
        const pluginCustomBox = panel.querySelector('[data-role="pluginCustomBox"]');
        const pluginTabChip = panel.querySelector('[data-role="pluginTabChip"]');

        const bypassStory = extEnabled && extOnly;
        if (extSwitch) extSwitch.checked = extEnabled;
        if (extBox) extBox.classList.toggle('open', extEnabled);
        if (extOnlySwitch) extOnlySwitch.checked = extOnly;
        if (storyOnlyWrap) storyOnlyWrap.classList.toggle('ufi-disabled', bypassStory);
        if (pluginOnlyBanner) pluginOnlyBanner.classList.toggle('hide', !bypassStory);
        if (pluginCustomBox) pluginCustomBox.classList.toggle('open', extPolicyMode === 'custom');
        if (pluginTabChip) {
            pluginTabChip.textContent = !extEnabled ? '关' : (extPolicyMode === 'custom' ? '独立' : '跟随');
            pluginTabChip.className = 'ufi-cnt';
        }

        panel.querySelectorAll('input[name="ufi-ext-policy-mode"]').forEach(radio => {
            const checked = radio.value === extPolicyMode;
            radio.checked = checked;
            radio.closest('.ufi-choice')?.classList.toggle('active', checked);
        });

        const pThinkSel = panel.querySelector('[data-role="pluginThinkingLevel"]');
        if (pThinkSel) pThinkSel.value = runtime.settings.pluginThinkingLevel || DEFAULTS.pluginThinkingLevel;

        const bindPluginSeg = (name, val) => {
            panel.querySelectorAll(`input[name="${name}"]`).forEach(radio => {
                const checked = radio.value === val;
                radio.checked = checked;
                radio.closest('.ufi-choice')?.classList.toggle('active', checked);
            });
        };
        bindPluginSeg('ufi-plugin-conflict', runtime.settings.pluginNativeThinkingMode || DEFAULTS.pluginNativeThinkingMode);
        bindPluginSeg('ufi-plugin-extra-inj', runtime.settings.pluginExtraInjection || DEFAULTS.pluginExtraInjection);
        bindPluginSeg('ufi-plugin-routing', runtime.settings.externalPluginRoutingLevel || DEFAULTS.externalPluginRoutingLevel);
        bindPluginSeg('ufi-plugin-jailbreak', runtime.settings.externalPluginJailbreak || DEFAULTS.externalPluginJailbreak);
        bindPluginSeg('ufi-plugin-input-mode', runtime.settings.pluginInputMode || DEFAULTS.pluginInputMode);
        bindPluginSeg('ufi-plugin-tool', runtime.settings.pluginToolTransport || DEFAULTS.pluginToolTransport);

        // 插件破甲有效状态 -> 控制插件输入转义可用性
        const effPluginJailbreak = runtime.settings.externalPluginJailbreak === 'follow' || extPolicyMode === 'follow'
            ? jailbreakOn
            : runtime.settings.externalPluginJailbreak === 'on';
        const pluginInputRow = panel.querySelector('[data-role="pluginInputModeRow"]');
        const pluginInputNote = panel.querySelector('[data-role="pluginInputOffNote"]');
        if (pluginInputRow) pluginInputRow.classList.toggle('ufi-disabled', !effPluginJailbreak);
        if (pluginInputNote) pluginInputNote.classList.toggle('hide', effPluginJailbreak);

        // v4.5.12：插件工具调用抗截断（同属破甲子项）
        const pluginToolVal = runtime.settings.pluginToolTransport || DEFAULTS.pluginToolTransport;
        const pluginToolRow = panel.querySelector('[data-role="pluginToolTransportRow"]');
        const pluginToolOffNote = panel.querySelector('[data-role="pluginToolOffNote"]');
        const pluginToolNote = panel.querySelector('[data-role="pluginToolNote"]');
        if (pluginToolRow) pluginToolRow.classList.toggle('ufi-disabled', !effPluginJailbreak);
        if (pluginToolOffNote) pluginToolOffNote.classList.toggle('hide', effPluginJailbreak);
        if (pluginToolNote) {
            pluginToolNote.textContent = pluginToolVal === 'on'
                ? '开：柏宝书记忆 / 柏宝绘生图 / 其余通用插件'
                : pluginToolVal === 'off'
                    ? '关：插件请求一律普通传输'
                    : `跟随：正文 5.1 当前${toolOn ? '开' : '关'}，仅柏宝书记忆/柏宝绘生图`;
        }

        // 插件实时生效预览（直接复用 resolvePolicyForRequest）
        const previewEl = panel.querySelector('[data-role="pluginLivePreview"]');
        if (previewEl) {
            if (!masterOn) {
                previewEl.innerHTML = '<div class="ufi-preview-title">实时生效预览</div><div class="ufi-preview-line">总开关已关闭：所有插件与后台请求均 0 改动原样放行。</div>';
            } else if (!extEnabled) {
                previewEl.innerHTML = '<div class="ufi-preview-title">实时生效预览</div><div class="ufi-preview-line">插件接管已关闭：所有正文外插件与后台请求均原样放行。</div>';
            } else {
                // 预览按「请求未受其他条件限制」假设工具判定通过，以展示设置意图
                const previewShape = { isGoogleNative: false, srcLower: '', toolDecision: { enabled: true, reason: '' } };
                const memP = resolvePolicyForRequest(runtime.settings, 'baibai_memory', modelCtx, previewShape);
                const scriptP = resolvePolicyForRequest(runtime.settings, 'script', modelCtx, previewShape);
                const qrP = resolvePolicyForRequest(runtime.settings, 'baibai_query_rewrite', modelCtx, previewShape);
                const imgP = resolvePolicyForRequest(runtime.settings, 'baibai_image_tag', modelCtx, previewShape);
                const rText = r => ({ off: '关', clean: '1档', demote: '2档' }[r] || r);
                const iText = m => ({ off: '关', json_escape: '整包转义', compact: '码点转义', hybrid_image: '输入转图片', full_armor: '深度破盾' }[m] || m);
                const fmtLine = (label, p) => {
                    const tp = p.thinkingPlan;
                    return `${label}：思考 <b>${escapeHtml(tp.level === 'forbid' ? '—' : tp.level)}</b> · 原生思考 <b>${escapeHtml(nativeThinkingModeLabel(tp.nativeMode || (tp.sanitizeThinkingConflict ? 'allow' : 'preset')))}</b> · 塞垃圾 <b>${p.extraInjection ? '开' : '关'}</b> · 防路由 <b>${rText(p.routingLevel)}</b> · 破甲 <b>${p.jailbreak ? '开' : '关'}</b> · 工具抗截断 <b>${p.useToolTransport ? '开' : '关'}</b> · 转义 <b>${iText(p.inputMode)}</b>`;
                };
                previewEl.innerHTML = [
                    '<div class="ufi-preview-title">实时生效预览</div>',
                    `<div class="ufi-preview-line">${fmtLine('柏宝书记忆', memP)}</div>`,
                    `<div class="ufi-preview-line">${fmtLine('通用插件', scriptP)}</div>`,
                    `<div class="ufi-preview-line">${fmtLine('向量重写', qrP)}</div>`,
                    `<div class="ufi-preview-line">${fmtLine('柏宝绘生图', imgP)}</div>`,
                ].join('');
            }
        }

        const entryState = getUiEntriesState();
        const enabledEntryCount = [entryState.floating, entryState.qr, entryState.menu].filter(Boolean).length;
        const entryCountBadge = panel.querySelector('[data-role="entryTabCount"]');
        if (entryCountBadge) entryCountBadge.textContent = String(enabledEntryCount);
        for (const [key, role, enabled] of [
            ['floating', 'entryFloatingEnabled', entryState.floating],
            ['qr', 'entryQrEnabled', entryState.qr],
            ['menu', 'entryMenuEnabled', entryState.menu],
        ]) {
            const input = panel.querySelector(`[data-role="${role}"]`);
            if (input) input.checked = enabled;
            const row = panel.querySelector(`[data-role="entryRow-${key}"]`);
            if (row) row.classList.toggle('active', enabled);
            const lock = panel.querySelector(`[data-role="entryLock-${key}"]`);
            if (lock) lock.style.display = enabled && enabledEntryCount <= 1 ? 'inline-flex' : 'none';
        }

        const autoUpdateSwitch = panel.querySelector('[data-role="autoUpdateEnabled"]');
        const autoUpdateOn = runtime.settings.autoUpdateEnabled !== false;
        if (autoUpdateSwitch) autoUpdateSwitch.checked = autoUpdateOn;
        const updateBadge = panel.querySelector('[data-role="updateBadge"]');
        const updateMsg = panel.querySelector('[data-role="updateStatusText"]');
        const updateTabState = panel.querySelector('[data-role="updateTabState"]');
        const checkBtn = panel.querySelector('[data-action="checkUpdate"]');
        const reloadBtn = panel.querySelector('[data-action="reloadForUpdate"]');
        const st = runtime.updateState || {};
        let tagText = '已是最新';
        let tabText = autoUpdateOn ? '开' : '关';
        if (st.status === 'checking') { tagText = '检查中…'; tabText = '…'; }
        else if (st.status === 'updated') { tagText = '已更新，待刷新'; tabText = '新'; }
        else if (st.status === 'up-to-date') { tagText = '已是最新'; }
        else if (st.status === 'manual-required' || st.status === 'not-installed') {
            tagText = '有新版 v' + (st.latestVersion || VERSION);
            tabText = '新';
        }
        else if (st.status === 'error') { tagText = '离线 / 检查失败'; }
        if (updateBadge) updateBadge.textContent = tagText;
        if (updateTabState) updateTabState.textContent = tabText;
        if (updateMsg) updateMsg.textContent = st.message || ('当前 v' + VERSION + ' · 等待检查');
        if (checkBtn) {
            checkBtn.disabled = st.status === 'checking';
            checkBtn.textContent = st.status === 'checking' ? '正在检查…' : '立即检查';
        }
        if (reloadBtn) {
            reloadBtn.style.display = st.needsReload ? 'inline-flex' : 'none';
            reloadBtn.style.alignItems = 'center';
        }

        const logCountBadge = panel.querySelector('[data-role="logTabCount"]');
        if (logCountBadge) logCountBadge.textContent = String(runtime.runHistory.length);
        const logPresetEl = panel.querySelector('[data-role="logActivePreset"]');
        if (logPresetEl) logPresetEl.textContent = detectActivePresetName() || '未读取';
        const logListEl = panel.querySelector('[data-role="logList"]');
        if (logListEl) {
            if (!runtime.runHistory.length) {
                logListEl.innerHTML = '<div class="ufi-log-empty">暂无生成记录，发送一条消息后自动在此显示详情</div>';
            } else {
                const escMap = {
                    json_escape: '一·整包 \\uXXXX',
                    compact: '二·码点 ⟦U:...⟧',
                    hybrid_image: '三·转图片',
                    full_armor: '四·深度破盾',
                    off: '未开启',
                };
                const routeMap = { off: '关', clean: '1档', demote: '2档' };
                logListEl.innerHTML = runtime.runHistory.map(item => {
                    const isStory = item.requestTier === 'story';
                    const isBypassed = Boolean(item.bypassed);
                    const isActive = runtime.activeRuns.has(item.id);
                    const isErr = !isActive && (item.phase === 'error' || item.error);
                    const isCancelled = !isActive && (item.phase === 'cancelled' || item.cancelled) && !(item.recoveredChars > 0);
                    const cardCls = isErr || isCancelled
                        ? 'ufi-log-card err'
                        : (isBypassed ? 'ufi-log-card bypass' : (isStory ? 'ufi-log-card story' : 'ufi-log-card plugin'));
                    const d = new Date(item.time || Date.now());
                    const pad = n => String(n).padStart(2, '0');
                    const timeStr = `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
                    const tierChip = isStory
                        ? '<span class="ufi-chip">正文请求</span>'
                        : item.requestTier === 'baibai_query_rewrite'
                            ? '<span class="ufi-chip gray">柏宝书·向量重写</span>'
                            : String(item.requestTier || '').startsWith('baibai_memory')
                                ? '<span class="ufi-chip gray">柏宝书·记忆摘要</span>'
                                : item.requestTier === 'baibai_image_tag'
                                    ? '<span class="ufi-chip gray">柏宝绘·生图</span>'
                                    : item.requestTier === 'baibai_image_char'
                                        ? '<span class="ufi-chip gray">柏宝绘·外貌</span>'
                                        : item.requestTier === 'baibai_image_workflow'
                                            ? '<span class="ufi-chip gray">柏宝绘·工作流</span>'
                                            : (item.requestTier === 'script'
                                                ? '<span class="ufi-chip gray">后台脚本/辅助</span>'
                                                : '<span class="ufi-chip gray">插件/后台</span>');
                    let stateChip = '<span class="ufi-chip">✅ 完成</span>';
                    if (isActive) {
                        stateChip = '<span class="ufi-chip warn">🟢 流式传输中…</span>';
                    } else if (isErr) {
                        stateChip = `<span class="ufi-chip warn">⚠️ 异常 (${escapeHtml(item.error || '中断')})</span>`;
                    } else if (isCancelled) {
                        stateChip = '<span class="ufi-chip gray">⏹ 手动停止</span>';
                    } else if (isBypassed) {
                        stateChip = `<span class="ufi-chip gray">⏭ 原样放行 (${escapeHtml(item.bypassReason || 'bypassed')})</span>`;
                    }
                    let toolStatus = '未开启';
                    if (isBypassed) {
                        toolStatus = '已放行 (未改动)';
                    } else if (item.maintenanceMode) {
                        toolStatus = 'Google原生跳过';
                    } else if (item.outputMode === 'tool') {
                        toolStatus = item.syntheticHit
                            ? '✅ 已注入并命中剥壳'
                            : (isActive ? '⏳ 已注入 (等待首包命中)' : '⚠️ 已注入但上游未调用工具');
                    } else if (item.transportBypassReason === 'jailbreak-disabled') {
                        toolStatus = '未开启 (破甲关)';
                    } else if (item.transportBypassReason === 'model-own-anti-truncation') {
                        toolStatus = '已避让 (模型自带抗截断)';
                    } else if (item.transportBypassReason === 'non-story-payload') {
                        toolStatus = '不适用 (该类请求不走工具)';
                    } else if (item.transportBypassReason && item.transportBypassReason !== 'transport-disabled') {
                        toolStatus = `未注入 (${escapeHtml(item.transportBypassReason)})`;
                    }
                    const effInMode = item.inputModeApplied || item.inputMode || 'off';
                    const escStatus = isBypassed ? '已放行' : (escMap[effInMode] || '未开启');
                    const ttftStr = item.firstContentMs != null
                        ? (item.firstContentMs / 1000).toFixed(1) + 's'
                        : (item.firstByteMs != null ? (item.firstByteMs / 1000).toFixed(1) + 's (首字节)' : '等待中');
                    const durStr = ((item.duration || 0) / 1000).toFixed(1) + 's';
                    const fmtTok = n => (typeof n === 'number' && Number.isFinite(n)) ? n.toLocaleString('en-US') : '0';
                    const hasActualInTok = typeof item.actualInputTokens === 'number' && item.actualInputTokens >= 0;
                    const hasEstInTok = typeof item.estimatedInputTokens === 'number' && item.estimatedInputTokens > 0;
                    const cachedNote = (typeof item.cachedInputTokens === 'number' && item.cachedInputTokens > 0)
                        ? ` · 缓存${fmtTok(item.cachedInputTokens)}`
                        : '';
                    const sendTokStr = hasActualInTok
                        ? `${fmtTok(item.actualInputTokens)} tok (实测${cachedNote})`
                        : (hasEstInTok ? `~${fmtTok(item.estimatedInputTokens)} tok (本地估算)` : '未统计');
                    const addedTok = typeof item.pluginAddedInputTokens === 'number' ? item.pluginAddedInputTokens : 0;
                    const rawTok = typeof item.rawEstimatedInputTokens === 'number' ? item.rawEstimatedInputTokens : 0;
                    const injectTokStr = addedTok > 0
                        ? `约 +${fmtTok(addedTok)} tok (原 ~${fmtTok(rawTok)})`
                        : `+0 tok (原 ~${fmtTok(rawTok)})`;
                    const thinkVal = item.thinkingLevelApplied || 'auto';
                    const conflictVal = nativeThinkingModeLabel(item.nativeThinkingModeApplied || (item.sanitizeThinkingConflictApplied ? 'allow' : 'preset'));
                    const routeVal = routeMap[item.routingLevelApplied] || '1档';
                    const jbVal = item.jailbreakApplied ? '开' : '关';
                    const extInjVal = item.extraInjectionApplied ? '开' : '关';
                    const libStr = `Sys:${item.textLibraryPromptMatches || 0} / User:${item.textLibraryUserMatches || 0}`;
                    const sysDemoteStr = item.demotedSystemCount ? `降权 ${item.demotedSystemCount} 条` : '保持原样';
                    const hasActualOutTok = typeof item.actualOutputTokens === 'number' && item.actualOutputTokens > 0;
                    const estOutTok = typeof item.estimatedOutputTokens === 'number' && item.estimatedOutputTokens > 0
                        ? item.estimatedOutputTokens
                        : (item.recoveredChars > 0 ? Math.ceil(item.recoveredChars * 0.9) : 0);
                    const outTokVal = hasActualOutTok ? item.actualOutputTokens : estOutTok;
                    const isProgressiveOut = item.progressive === true || ((item.upstreamRecords || 0) >= 4 && (item.duration || 0) > (item.firstContentMs || 0) + 800);
                    const genMs = (isProgressiveOut && item.firstContentMs != null && (item.duration || 0) > item.firstContentMs + 800)
                        ? ((item.duration || 0) - item.firstContentMs)
                        : (item.duration || 0);
                    const tokPerSec = (outTokVal > 0 && genMs > 0) ? (outTokVal / (genMs / 1000)).toFixed(1) : null;
                    const outTokStr = outTokVal > 0
                        ? `${hasActualOutTok ? '' : '~'}${fmtTok(outTokVal)} tok${tokPerSec ? ` · ${tokPerSec} tok/s` : ''}`
                        : '0 tok';
                    const extraNotes = [];
                    if (item.toolPlusArmorInjected) extraNotes.push('工具+排版协同已注入');
                    if (item.finishReasons?.length) extraNotes.push('结束原因: ' + item.finishReasons.join(','));
                    if (item.errorMessage) extraNotes.push('详情: ' + item.errorMessage);
                    if (item.warning) extraNotes.push('提示: ' + item.warning);
                    return [
                        `<div class="${cardCls}">`,
                        '<div class="ufi-log-top">',
                        `<span>#${item.id}</span>`,
                        tierChip,
                        stateChip,
                        `<span class="ufi-log-time">${timeStr}</span>`,
                        '</div>',
                        '<div class="ufi-log-grid">',
                        `<div>模型/通道：<b>${escapeHtml(item.detectedModel || item.modelProfile || '未知')}${item.maintenanceMode ? ' · 原生维护' : ''}</b></div>`,
                        `<div>当前预设：<b>${escapeHtml(item.activePreset || '未读取')}</b></div>`,
                        `<div>思考/原生：<b>${escapeHtml(thinkVal === 'forbid' ? '—' : thinkVal)} · 原生思考 ${escapeHtml(conflictVal)}</b></div>`,
                        `<div>防路由/破甲/塞垃圾：<b>${routeVal} · ${jbVal} · ${extInjVal}</b></div>`,
                        `<div>工具抗截断：<b>${toolStatus}</b></div>`,
                        `<div>输入转义：<b>${escStatus}</b></div>`,
                        isBypassed
                            ? `<div>放行字节：<b>${fmtTok(item.upstreamBytes || 0)} B</b> (直连未拆帧)</div>`
                            : `<div>输出 Token：<b>${outTokStr}</b> (${item.upstreamRecords || 0} 帧)</div>`,
                        `<div>发送 Token：<b>${sendTokStr}</b></div>`,
                        `<div>注入开销（本地估算）：<b>${injectTokStr}</b></div>`,
                        `<div>首字/总耗时：<b>${ttftStr} / ${durStr}</b></div>`,
                        `<div>稀释命中/Sys：<b>${libStr} · ${sysDemoteStr}</b></div>`,
                        '</div>',
                        extraNotes.length ? `<div class="ufi-log-foot">${escapeHtml(extraNotes.join(' | '))}</div>` : '',
                        '</div>',
                    ].join('');
                }).join('');
            }
        }

        try { updateFabStatus(); } catch (_) {}

        const statusEl = panel.querySelector('[data-role="status"]');
        if (statusEl) statusEl.textContent = runDescription(runtime.lastRun);
    }

