                    notify('warning', ctx.detectedModel ? `通用模型：${ctx.detectedModel}` : '未读取到酒馆当前模型');
                }
                return;
            }
            const paddingSampleBtn = event.target?.closest?.('[data-action="paddingSample"]');
            if (paddingSampleBtn) {
                const kind = paddingSampleBtn.dataset.kind === 'user' ? 'user' : 'system';
                const slot = kind === 'user' ? 'userCustom' : 'systemCustom';
                const existing = String(runtime.textLibrary?.[slot] || '').trim();
                if (existing) {
                    const confirmFn = panel.ownerDocument?.defaultView?.confirm;
                    if (typeof confirmFn === 'function' && !confirmFn.call(panel.ownerDocument.defaultView, '当前栏已有内容，确定用默认文本覆盖吗？')) return;
                }
                const sample = buildNeutralPaddingBlock(
                    kind,
                    kind === 'user' ? PADDING_BUDGET.userChars : PADDING_BUDGET.systemChars,
                    runtime.runSerial + (kind === 'user' ? 7 : 1)
                );
                setCustomPaddingText(kind, sample, { notify: false });
                notify('info', `已恢复默认文本到${kind === 'user' ? '输入' : '头部'}垃圾（${sample.length} 字），可直接修改`);
                return;
            }
            const salvageLastBtn = event.target?.closest?.('[data-action="salvageLast"]');
            if (salvageLastBtn) {
                salvageLastRawResponseIntoChat().catch(() => {});
                return;
            }
            const clearLogsBtn = event.target?.closest?.('[data-action="clearLogs"]');
            if (clearLogsBtn) {
                runtime.runHistory.length = 0;
                runtime.lastRun = null;
                runtime.lastStoryRun = null;
                syncConfigPanel();
                notify('info', '已清空请求日志');
                return;
            }
            const checkBtn = event.target?.closest?.('[data-action="checkUpdate"]');
            if (checkBtn) {
                checkForUpdate({ manual: true }).catch(() => {});
                return;
            }
            const reloadBtn = event.target?.closest?.('[data-action="reloadForUpdate"]');
            if (reloadBtn) {
                if (runtime.activeRuns.size > 0) {
                    notify('warning', '当前仍有生成请求正在进行，请稍候完成后再刷新页面');
                    return;
                }
                try {
                    const host = rootWindow();
