        visualViewport?.addEventListener?.('scroll', onViewportChange);
        runtime.panelStops.push(() => panel.removeEventListener('click', onClick));
        runtime.panelStops.push(() => panel.removeEventListener('change', onChange));
        runtime.panelStops.push(() => panel.removeEventListener('input', onInput));
        runtime.panelStops.push(() => doc.removeEventListener('keydown', onKey, true));
        runtime.panelStops.push(() => hostView?.removeEventListener?.('resize', onViewportChange));
        runtime.panelStops.push(() => hostView?.removeEventListener?.('orientationchange', onViewportChange));
        runtime.panelStops.push(() => visualViewport?.removeEventListener?.('resize', onViewportChange));
        runtime.panelStops.push(() => visualViewport?.removeEventListener?.('scroll', onViewportChange));
        syncConfigPanelViewport();
        syncConfigPanel();
        return true;
    }

    function openConfigPanel() {
        if (!mountConfigPanel()) return false;
        const panel = runtime.panel;
        const doc = panel.ownerDocument;
        runtime.lastFocusedElement = doc.activeElement;
