        switchPanelTab(runtime.panelTab || 'story');
        syncConfigPanelViewport();
        try { updateFabStatus(); } catch (_) {}
        panel.classList.add('visible');
        panel.setAttribute('aria-hidden', 'false');
        try { panel.querySelector('.ufi-close')?.focus({ preventScroll: true }); } catch (_) {}
        try { doc.defaultView?.requestAnimationFrame(syncConfigPanelViewport); } catch (_) {}
        return true;
    }

    // ==================== 悬浮球入口与酒馆助手工具栏接入 ====================

    function mountFallbackLauncher() {
        if (runtime.settings.entryFloatingEnabled === false) {
            unmountFallbackLauncher();
            return false;
        }
        const doc = hostDocument();
        if (!doc?.body) return false;
        unmountFallbackLauncher();
        if (!doc.getElementById(STYLE_ID)) {
            const style = doc.createElement('style');
            style.id = STYLE_ID;
            style.dataset.instanceId = INSTANCE_ID;
            style.textContent = configPanelCss();
            (doc.head || doc.documentElement).appendChild(style);
            runtime.style = style;
        }
        const button = doc.createElement('button');
        button.id = FALLBACK_LAUNCHER_ID;
        button.dataset.instanceId = INSTANCE_ID;
        button.type = 'button';
        button.setAttribute('aria-label', '打开双马尾插件控制台（拖动可移动 / 右键切换省流模式）');

        // 位置：优先用存档坐标，其次兼容旧版 {dock,right,bottom} 存档，最后落在右下角
        const saved = readFabPos();
        let pos;
        if (saved && typeof saved.x === 'number' && typeof saved.y === 'number') {
            pos = clampFabPos(doc, saved.x, saved.y);
        } else if (saved && (typeof saved.right === 'number' || typeof saved.bottom === 'number')) {
            const view = doc.defaultView;
            const vw = Number(view?.innerWidth || 1280);
            const vh = Number(view?.innerHeight || 800);
            const right = typeof saved.right === 'number' ? saved.right : FAB_DEFAULT_RIGHT;
            const bottom = typeof saved.bottom === 'number' ? saved.bottom : FAB_DEFAULT_BOTTOM;
            pos = clampFabPos(doc, vw - FAB_SIZE - right, vh - FAB_SIZE - bottom);
        } else {
            pos = defaultFabPos(doc);
        }
        placeFab(button, pos);

        // 拖拽：鼠标与触摸各挂一套，位移超过 5px 才算拖动，否则松手就打开控制台
        let drag = null;
        let lastTapAt = 0;
        const onDown = ev => {
            if (ev.type === 'mousedown' && ev.button !== 0) return;
            const p = ev.touches ? ev.touches[0] : ev;
            if (!p) return;
            drag = {
                sx: p.clientX,
                sy: p.clientY,
                ox: parseFloat(button.style.left) || 0,
                oy: parseFloat(button.style.top) || 0,
                moved: false,
            };
        };
        const onMove = ev => {
            if (!drag) return;
            const p = ev.touches ? ev.touches[0] : ev;
            if (!p) return;
            const dx = p.clientX - drag.sx;
            const dy = p.clientY - drag.sy;
            if (!drag.moved && Math.abs(dx) < 5 && Math.abs(dy) < 5) return;
            drag.moved = true;
            button.classList.add('ufi-dragging');
            if (ev.cancelable) ev.preventDefault();
            placeFab(button, clampFabPos(doc, drag.ox + dx, drag.oy + dy));
        };
        const onUp = () => {
            if (!drag) return;
            const wasMoved = drag.moved;
            drag = null;
            button.classList.remove('ufi-dragging');
            if (wasMoved) {
                saveFabPos(parseFloat(button.style.left) || 0, parseFloat(button.style.top) || 0);
                return;
            }
            const now = Date.now();
            if (now - lastTapAt < 350) return;
            lastTapAt = now;
            openConfigPanel();
        };
        const onContext = ev => {
            ev.preventDefault?.();
            ev.stopPropagation?.();
            setPluginEnabled(!(runtime.settings.pluginEnabled !== false));
        };
        button.addEventListener('mousedown', onDown);
        button.addEventListener('touchstart', onDown, { passive: true });
        button.addEventListener('contextmenu', onContext);
        doc.addEventListener('mousemove', onMove);
        doc.addEventListener('touchmove', onMove, { passive: false });
        doc.addEventListener('mouseup', onUp);
        doc.addEventListener('touchend', onUp);
        doc.body.appendChild(button);
        runtime.launcher = button;
        syncLauncherAppearance();

        // 挂载后自检：尺寸为 0 或整颗跑出视口时，拉回右下角
        const verifyTimer = setTimeout(() => {
            if (!button.isConnected) return;
            const view = doc.defaultView;
            const vw = Number(view?.innerWidth || 0);
            const vh = Number(view?.innerHeight || 0);
            const rect = button.getBoundingClientRect();
            const lost = rect.width < 8 || rect.height < 8
                || rect.right <= 8 || rect.left >= vw - 8 || rect.bottom <= 8 || rect.top >= vh - 8;
            if (!lost) return;
            const fix = defaultFabPos(doc);
            placeFab(button, fix);
            saveFabPos(fix.x, fix.y);
        }, 600);
        runtime.floatingStops.push(() => {
            clearTimeout(verifyTimer);
            button.removeEventListener('mousedown', onDown);
            button.removeEventListener('touchstart', onDown);
            button.removeEventListener('contextmenu', onContext);
            doc.removeEventListener('mousemove', onMove);
            doc.removeEventListener('touchmove', onMove);
            doc.removeEventListener('mouseup', onUp);
            doc.removeEventListener('touchend', onUp);
        });
        return true;
    }

    function toolbarApi() {
        const bindFrom = (obj, fnName) => (typeof obj?.[fnName] === 'function' ? obj[fnName].bind(obj) : null);
        const candidates = [];
        try {
            const localTh = typeof TavernHelper !== 'undefined' ? TavernHelper : null;
            candidates.push({
                eventOn: typeof eventOn === 'function' ? eventOn : bindFrom(localTh, 'eventOn'),
                getButtonEvent: typeof getButtonEvent === 'function' ? getButtonEvent : bindFrom(localTh, 'getButtonEvent'),
                appendButtons: typeof appendInexistentScriptButtons === 'function'
                    ? appendInexistentScriptButtons
                    : (bindFrom(localTh, 'appendInexistentScriptButtons') || bindFrom(localTh, 'replaceScriptButtons')),
                getButtons: typeof getScriptButtons === 'function' ? getScriptButtons : bindFrom(localTh, 'getScriptButtons'),
                replaceButtons: typeof replaceScriptButtons === 'function' ? replaceScriptButtons : bindFrom(localTh, 'replaceScriptButtons'),
            });
        } catch (_) {}

        for (const win of hostWindows()) {
            try {
                const th = win?.TavernHelper || null;
                candidates.push({
                    eventOn: bindFrom(win, 'eventOn') || bindFrom(th, 'eventOn'),
                    getButtonEvent: bindFrom(win, 'getButtonEvent') || bindFrom(th, 'getButtonEvent'),
                    appendButtons: bindFrom(win, 'appendInexistentScriptButtons') || bindFrom(th, 'appendInexistentScriptButtons') || bindFrom(th, 'replaceScriptButtons'),
                    getButtons: bindFrom(win, 'getScriptButtons') || bindFrom(th, 'getScriptButtons'),
                    replaceButtons: bindFrom(win, 'replaceScriptButtons') || bindFrom(th, 'replaceScriptButtons'),
                });
            } catch (_) {}
        }

        return candidates.find(c => c.eventOn && c.getButtonEvent) || null;
    }

    function registerLauncher() {
        let hasThBtn = false;
        try {
            const api = toolbarApi();
            if (api) {
                if (api.getButtons && api.replaceButtons) {
                    const mig = migrateLegacyScriptButtons(api.getButtons());
                    if (mig.changed) {
                        try { api.replaceButtons(mig.buttons); } catch (_) {}
                    }
                }
                if (runtime.settings.entryQrEnabled !== false) {
                    try { api.appendButtons?.([{ name: LAUNCHER_BUTTON_NAME, visible: true }]); } catch (_) {}
                    hasThBtn = true;
                } else {
                    syncTavernScriptButtonVisibility(false);
                }
                const stop = api.eventOn(api.getButtonEvent(LAUNCHER_BUTTON_NAME), openConfigPanel);
                if (typeof stop === 'function') runtime.uiStops.push(stop);
                else if (stop && typeof stop.stop === 'function') runtime.uiStops.push(() => stop.stop());
            }
        } catch (err) {
            console.warn(`[${SCRIPT_NAME}] 注册酒馆脚本按钮失败`, err);
        }

        const hasFab = mountFallbackLauncher();
        const hasDirect = mountDirectQrAndMenuButtons();

        for (const delay of [450, 1400, 3000]) {
            const t = setTimeout(() => { if (!runtime.disposed) ensureDesktopFloatingVisible(); }, delay);
            runtime.uiStops.push(() => clearTimeout(t));
        }
        const poll = setInterval(() => {
            if (!runtime.disposed) ensureDesktopFloatingVisible();
        }, 4200);
        runtime.uiStops.push(() => clearInterval(poll));

        const doc = hostDocument();
        return [
            hasThBtn && 'th-qr',
            doc?.getElementById?.(QR_DOM_BTN_ID) && 'dom-qr',
            doc?.getElementById?.(EXT_MENU_ITEM_ID) && 'menu',
            hasFab && 'floating',
        ].filter(Boolean).join('+') || (hasDirect ? 'direct' : 'none');
    }

    // ==================== 对外 API、状态查询与生命周期 ====================

    function status() {
        return {
            version: VERSION,
            instanceId: INSTANCE_ID,
            installed: runtime.installed,
            activeRequests: runtime.activeRuns.size,
            settings: { ...runtime.settings },
            updateState: { ...runtime.updateState },
            capabilities: Array.from(runtime.capabilities.values(), item => ({ ...item })),
            lastRun: runtime.lastRun ? { ...runtime.lastRun } : null,
            lastStoryRun: runtime.lastStoryRun ? { ...runtime.lastStoryRun } : null,
            runHistory: runtime.runHistory.map(item => ({ ...item })),
        };
    }

    function exposeApi() {
        const host = rootWindow();
        const api = {
            instanceId: INSTANCE_ID,
            version: VERSION,
            openPanel: openConfigPanel,
            closePanel: closeConfigPanel,
            getStatus: status,
            setPluginEnabled,
            setHydrogenThinkingLevel,
            setOtherThinkingLevel,
            setSessionSaltEnabled,
            setSanitizeThinkingConflict,
            setNativeThinkingMode,
            setForbidReasoningEffort,
            setExtraInjectionEnabled,
            setAutoBypassVertex,
            setRoutingLevel,
            setJailbreakEnabled,
            setToolTransport,
            setToolOuterCoverEnabled,
            setInputEscapeEnabled,
            setInputMode,
            setPreserveTrailingPrefill,
            setExternalPluginEnabled,
            setExternalPluginOnly,
            setExternalPluginPolicyMode,
            setPluginThinkingLevel,
            setPluginSessionSalt,
            setPluginSanitizeThinkingConflict,
            setPluginNativeThinkingMode,
            setPluginExtraInjection,
            setPluginRoutingLevel,
            setPluginJailbreak,
            setPluginInputMode,
            setPluginToolTransport,
            setCustomPaddingEnabled,
            setCustomPaddingLoopFill,
            setCustomPaddingText,
            getCustomPaddingLibrary,
            setExternalPlugin(enabled, mode, pluginOnly) {
                runtime.settings.externalPluginEnabled = Boolean(enabled);
                if (mode === 'follow' || mode === 'custom') {
                    runtime.settings.externalPluginPolicyMode = mode;
                } else if (mode === 'route_only' || mode === 'full_inject') {
                    applyLegacyExternalPluginMode(runtime.settings, mode);
                }
                if (!runtime.settings.externalPluginEnabled) {
                    runtime.settings.externalPluginOnly = false;
                } else if (typeof pluginOnly === 'boolean') {
                    runtime.settings.externalPluginOnly = pluginOnly;
                }
                saveSettings();
                syncFetchInstallation();
                syncStPostProcessingForToolTransport();
                autoEnsureCompanionTavernRegex();
                syncConfigPanel();
                try { updateFabStatus(); } catch (_) {}
                return {
                    enabled: runtime.settings.externalPluginEnabled,
                    policyMode: runtime.settings.externalPluginPolicyMode,
                    pluginOnly: runtime.settings.externalPluginOnly,
                };
            },
            setSystemDemote(enabled) {
                return setRoutingLevel(enabled ? 'demote' : 'clean', { notify: false }) === 'demote';
            },
            applyTextLibraryMarkers,
            compactEncode,
            prepareRequest,
            extractContent,
            checkForUpdate,
            setAutoUpdateEnabled,
            setUiEntries,
            getUiEntries: getUiEntriesState,
            salvageLastResponse: salvageLastRawResponseIntoChat,
            dispose,
            _internals: Object.freeze({
                SETTINGS_SCHEMA,
                DEFAULTS,
                MASK_SEP,
                normalizeSchemaValue,
                migrateSettings,
                detectActivePresetName,
                maskNSFWTokens,
                maskNSFWTokensSafe,
                decodeCompactCodepoints,
                unmaskNSFWTokens,
                stripLeakedInjectedArtifacts,
                StreamingUnmasker,
                encodeCurrentUserTurn,
                matchingRequestIndices,
                applyFullContextCodepointArmorInPlace,
                normalizeOpenAiResponse,
                handleResilientPlainJsonResponse,
                isProtectedToolOrSignatureMessage,
                isOwnTool,
                ArgumentReader,
                ResponseStream,
                salvageIncompletePayload,
                teeCacheResponse,
                transformStreamResponse,
                createResilientPlainSseResponse,
                salvageLastRawResponseIntoChat,
                getLastRawStream: () => runtime.lastRawStream,
                resolveModelContext,
                resolveThinkingPlan,
                resolvePolicyForRequest,
                sanitizeForArgonClassifiers,
                buildStreamTypesettingSpec,
                autoEnsureCompanionTavernRegex,
                loadSettings,
                saveSettings,
                getSettings: () => ({ ...runtime.settings }),
                getPanel: () => runtime.panel,
                getRunHistory: () => runtime.runHistory.slice(),
                hasKonatanPresetSignature,
                hasTransAmPresetSignature,
                hasKnownStoryPresetSignature,
                isStandaloneUserFloorMessage,
                isPrimaryStoryTurnRequest,
                isMainGenerationRequest,
                isPluginOnlyBypassStoryMode,
            }),
        };
        Object.assign(host, {
            [API_NAME]: api,
            [LOADED_FLAG]: true,
            [STATE_NAME]: { instanceId: INSTANCE_ID, mountedAt: Date.now() },
        });
    }

    function dispose(reason = 'manual') {
        if (runtime.disposed) return;
        runtime.disposed = true;
        runtime.activeRuns.forEach(item => item.abort('script-disposed'));
        runtime.activeRuns.clear();
        removeFetch();
        clearPanelStops();
        runtime.lastFocusedElement = null;
        unmountFallbackLauncher();
        unmountQrButton();
        unmountMenuEntry();
        drainStops(runtime.uiStops);
        for (const node of [runtime.panel, runtime.style, runtime.launcher]) {
            try { node?.remove?.(); } catch (_) {}
        }
        const topHost = rootWindow();
        for (const key of [API_NAME, STATE_NAME]) {
            if (topHost[key]?.instanceId === INSTANCE_ID) {
                try { delete topHost[key]; } catch (_) { topHost[key] = undefined; }
            }
        }
        topHost[LOADED_FLAG] = false;
        console.log(`[${SCRIPT_NAME}] 卸载完成：${reason}`);
    }

    function init() {
        const host = rootWindow();
        const prev = host[API_NAME];
        if (prev && prev.instanceId !== INSTANCE_ID) {
            try { prev.dispose?.('replaced'); } catch (_) {}
        }
        cleanupLegacyAntiRouteResiduals();
        loadSettings();
        loadPaddingLibrary();
        exposeApi();
        syncFetchInstallation();
        primeThGenerationTracker();
        syncLauncherAppearance();

        runWhenHostCsrfReady(() => {
            if (runtime.disposed) return;
            syncStPostProcessingForToolTransport();
            autoEnsureCompanionTavernRegex();
            try {
                const stCtx = resolveStContext();
                if (stCtx?.chatCompletionSettings && stCtx.chatCompletionSettings.stream_openai === false) {
                    stCtx.chatCompletionSettings.stream_openai = true;
                    const doc = hostDocument();
                    const view = doc?.defaultView || rootWindow();
                    const toggle = doc?.getElementById?.('stream_toggle');
                    const Ev = view?.Event || (typeof Event === 'function' ? Event : null);
                    if (toggle && toggle.checked === false) {
                        toggle.checked = true;
                        if (Ev) toggle.dispatchEvent?.(new Ev('change', { bubbles: true }));
                    }
                }
            } catch (_) {}
        });

        try {
            const stCtx = resolveStContext();
            const es = stCtx?.eventSource;
            const et = stCtx?.event_types || stCtx?.eventTypes || {};
            if (es && typeof es.on === 'function') {
                const attachEvent = (evName, cb) => {
                    if (!evName) return;
                    es.on(evName, cb);
                    runtime.uiStops.push(() => {
                        try {
                            if (typeof es.removeListener === 'function') es.removeListener(evName, cb);
                            else if (typeof es.off === 'function') es.off(evName, cb);
                        } catch (_) {}
                    });
                };
                const onAfterReply = () => {
                    if (runtime.settings.pluginEnabled !== false) {
                        sanitizeLatestChatMessageInPlace();
                        setTimeout(sanitizeLatestChatMessageInPlace, 120);
                    }
                };
                attachEvent(et.MESSAGE_RECEIVED || 'message_received', onAfterReply);
                attachEvent(et.CHARACTER_MESSAGE_RENDERED || 'character_message_rendered', onAfterReply);
                attachEvent(et.GENERATION_ENDED || 'generation_ended', onAfterReply);
                attachEvent(et.GENERATION_STOPPED || 'generation_stopped', onAfterReply);

                // [停止生成修复] 酒馆点击停止时，主动中止本插件接管的所有在途请求并结束其下游流，
                // 不依赖酒馆的 AbortSignal 是否成功透传到被拦截的 fetch。
                const onStopAll = () => {
                    for (const r of Array.from(runtime.activeRuns.values())) {
                        try { r.abort(new DOMException('Clicked stop button', 'AbortError')); } catch (_) {}
                    }
                    // 兜底：1.2 秒后若酒馆按钮仍处于"生成中"外观，则静默强制恢复，避免只能刷新页面
                    setTimeout(() => {
                        try {
                            const doc = hostDocument();
                            const sendBtn = doc?.getElementById?.('send_but');
                            const stopBtn = doc?.getElementById?.('mes_stop');
                            const visible = el => {
                                if (!el) return false;
                                const view = doc.defaultView || window;
                                const cs = view.getComputedStyle ? view.getComputedStyle(el) : null;
                                return !(el.classList?.contains('displayNone') || cs?.display === 'none');
                            };
                            const sendHidden = sendBtn ? !visible(sendBtn) : false;
                            const stopShown = stopBtn ? visible(stopBtn) : false;
                            if (sendHidden || stopShown) {
                                const ctx = resolveStContext();
                                if (typeof ctx?.activateSendButtons === 'function') {
                                    ctx.activateSendButtons();
                                    console.log(`[${SCRIPT_NAME}] 停止后发送按钮未恢复，已自动恢复`);
                                }
                            }
                        } catch (_) {}
                    }, 1200);
                };
                attachEvent(et.GENERATION_STOPPED || 'generation_stopped', onStopAll);

                const onPresetSwap = () => {
                    if (!runtime.disposed) {
                        setTimeout(() => {
                            syncStPostProcessingForToolTransport();
                            syncConfigPanel();
                        }, 0);
                    }
                };
                attachEvent(et.PRESET_CHANGED || 'preset_changed', onPresetSwap);
                attachEvent(et.OAI_PRESET_CHANGED_AFTER || 'oai_preset_changed_after', onPresetSwap);
            }
        } catch (_) {}

        let updTimer = null;
        runtime.uiStops.push(() => {
            if (updTimer != null) {
                clearTimeout(updTimer);
                updTimer = null;
            }
        });
        if (runtime.settings.autoUpdateEnabled === true) {
            updTimer = setTimeout(() => {
                updTimer = null;
                if (!runtime.disposed && runtime.settings.autoUpdateEnabled === true) {
                    checkForUpdate({ manual: false }).catch(() => {});
                }
            }, 3000);
        }

        const mounted = registerLauncher();
        try { window.addEventListener('pagehide', () => dispose('pagehide'), { once: true }); } catch (_) {}
        console.log(`[${SCRIPT_NAME}] 已加载`, { mounted, settings: runtime.settings });
        notify('success', `${SCRIPT_NAME} 已加载`);
    }

    setTimeout(() => {
        try {
            init();
        } catch (err) {
            console.error(`[${SCRIPT_NAME}] 初始化失败`, err);
            notify('error', `初始化失败：${err?.message || String(err)}`);
        }
    }, 0);

})();
